// InsightDTO The per-role INSIGHT doc (T-3809): the judgement calls and trade-offs this role
// keeps reaching for. Third block of the role journal, alongside Duty (the role
// definition) and Learning (the lessons doc) — the owner asked for it because
// insight and learning had been sharing one document.
//
// “role_key“ scopes the doc to a role; there is NO “task_type“ axis (that is
// the lessons key, and it is deliberately absent here). Since T-e1e3 a role MAY
// have a factory seed, and unlike lessons that seed is PER-ROLE
// (“seeds/insight_<role_key>.md“) rather than one shared file — the assistant's
// judgement calls would be wrong for any other role. A role with no seed file
// still reads genuinely EMPTY until it writes.
//
// Insight is SEPARATE, not private. READ is unrestricted: any authenticated
// identity may read ANY role's insight — the same floor Duty and Learning sit on.
type InsightDTO struct {
	// CapChars The document size cap now in force, in CHARACTERS (the doc.cap_chars.insight setting). Served on the READ face so an agent can size an edit BEFORE writing it — the alternative is discovering the limit by being refused, and the settings surface is admin-only.
	CapChars *int `json:"cap_chars,omitempty"`

	// HasSeed True when a FACTORY VERSION of this role's insight exists to fall back to — i.e. `seeds/insight_<role_key>.md` ships. It answers ONLY that: it says nothing about whether the doc you are holding IS that factory version (`is_default` answers that), and the two are independent — a role with a seed that has since written its own reads has_seed=true, is_default=false. Added by T-6501 as the precondition for `reset_insight`: a role with has_seed=false gets a 404 from that route, so a surface offering the reset must gate on THIS field. Deliberately NOT named after `RoleDefDTO.is_seed`, which is a fact about the role's DUTY and was misread twice on 2026-08-04 as "you are reading the factory version".
	HasSeed *bool `json:"has_seed,omitempty"`

	// IsDefault True while this role has never written its own insight doc (or reset it). It does NOT imply an empty `text`: a role that ships with a factory seed (`seeds/insight_<role_key>.md`) reads that seed with is_default=true, while a role without one reads "". Read this field — not the emptiness of `text` — to tell factory wording apart from something a person wrote. It is NOT the same question as `has_seed`: this one is about what has been WRITTEN, that one about what exists to fall back TO.
	IsDefault     *bool   `json:"is_default,omitempty"`
	OwnerId       *string `json:"owner_id,omitempty"`
	RoleKey       *string `json:"role_key,omitempty"`
	SchemaVersion *int    `json:"schema_version,omitempty"`

	// SizeChars Size of `text` in CHARACTERS (Unicode code points) — the same unit as cap_chars.
	SizeChars *int    `json:"size_chars,omitempty"`
	Text      *string `json:"text,omitempty"`
}

// InsightEditDTO One “patch_insight“ edit: replace the occurrence of “old“ with “new“. “old“ must match the current doc EXACTLY ONCE (0 or >1 hits reject the whole batch — the unique anchor doubles as an optimistic concurrency check); an EMPTY “old“ appends “new“ at the end of the doc (joined with a newline when the doc does not already end in one).
type InsightEditDTO struct {
	New *string `json:"new,omitempty"`
	Old *string `json:"old,omitempty"`
}

// InsightPatchDTO Anchor-addressed PATCH of an insight doc: “{edits: [{old, new}], allow_shrink?}“. ATOMIC — edits apply sequentially to an in-memory copy and any failing anchor (absent or ambiguous “old“) rejects the ENTIRE batch with a flat 400 and ZERO writes. “allow_shrink“ (default false) must be set explicitly for a patch that empties the doc or shrinks it to under a tenth of its size — the same wipe-guard posture patch_lessons carries.
type InsightPatchDTO struct {
	AllowShrink *bool            `json:"allow_shrink,omitempty"`
	Edits       []InsightEditDTO `json:"edits"`
}

// InsightPatchResultDTO Receipt of an insight PATCH. “size_chars“ (CHARACTERS — Unicode code points, the SAME unit as the “doc.cap_chars.insight“ cap the write is judged against) and “sha256“ (hex) are lightweight verification anchors over the RESULTING doc text, so the caller can confirm the write landed without re-reading the full doc. “applied_edits“ counts the edits that changed the text THEY were handed — it is not a report on whether the document ended up different from where it started. A batch of no-ops reports 0, but a batch whose edits undo one another (“anchor → middle“ then “middle → anchor“) reports the full count over a document that never moved, and nothing is written in that case. To decide whether the doc actually changed, compare “sha256“ against the value you held before the call.
type InsightPatchResultDTO struct {
	AppliedEdits *int `json:"applied_edits,omitempty"`

	// CapChars The document size cap now in force, in CHARACTERS (the doc.cap_chars.insight setting) — the number this write was judged against.
	CapChars      *int    `json:"cap_chars,omitempty"`
	IsDefault     *bool   `json:"is_default,omitempty"`
	OwnerId       *string `json:"owner_id,omitempty"`
	RoleKey       *string `json:"role_key,omitempty"`
	SchemaVersion *int    `json:"schema_version,omitempty"`
	Sha256        *string `json:"sha256,omitempty"`

	// SizeChars Size of the RESULTING doc in CHARACTERS (Unicode code points) — the same unit as cap_chars.
	SizeChars *int `json:"size_chars,omitempty"`
}

// InsightReplaceDTO Whole-doc replace of an insight doc: “{text}“. “text“ is REQUIRED — a whole-doc replace must never infer "empty" from a missing key. “allow_shrink“ (default false) must be set explicitly to replace existing content with an empty doc — the same wipe-guard posture replace_lessons carries.
type InsightReplaceDTO struct {
	AllowShrink *bool  `json:"allow_shrink,omitempty"`
	Text        string `json:"text"`
}

