// does NOT carry and the cap each is judged against.
//
// “sop_md“ and “learnings“ are deliberately ABSENT rather than served empty:
// they are the bulk that made a listing unreadable, and an empty string in a
// field that normally holds the SOP reads as "this type has no SOP". Their
// sizes are measured on the STORED rows, so the row still answers "which manual
// is nearly full" — read the one you picked with get_task_manual.
type TaskManualListItemDTO struct {
	Assignee map[string]interface{} `json:"assignee"`

	// CapChars DEPRECATED since T-30f1 — read learnings_cap_chars or sop_md_cap_chars instead. The manual's SOP and learnings are judged by two SEPARATE caps now, and one field cannot report both: this one carries the LEARNINGS cap (doc.cap_chars.manual_learnings) only, and says nothing about sop_md. Kept so existing clients keep reading a real number rather than a zero.
	CapChars    *int                 `json:"cap_chars,omitempty"`
	DisplayName string               `json:"display_name"`
	Fields      []TaskManualFieldDTO `json:"fields"`

	// LearningsCapChars The cap on the type's learnings now in force, in CHARACTERS (the doc.cap_chars.manual_learnings setting). Served on the READ face so an agent can size an edit BEFORE writing it. Independent of sop_md_cap_chars since T-30f1.
	LearningsCapChars *int `json:"learnings_cap_chars,omitempty"`

	// LearningsChars Size of the type's learnings in CHARACTERS, measured on the STORED document — which this row does not carry. Reported PER CAPPED DOCUMENT rather than as one total, because learnings and sop_md are judged against their own caps since T-30f1.
	LearningsChars *int    `json:"learnings_chars,omitempty"`
	Purpose        *string `json:"purpose,omitempty"`

	// SopMdCapChars The cap on the type's sop_md now in force, in CHARACTERS (the doc.cap_chars.manual_sop setting). See learnings_cap_chars.
	SopMdCapChars *int `json:"sop_md_cap_chars,omitempty"`

	// SopMdChars Size of the type's sop_md in CHARACTERS, measured on the STORED document. See learnings_chars.
	SopMdChars *int     `json:"sop_md_chars,omitempty"`
	TypeKey    string   `json:"type_key"`
	UpdatedTs  *float64 `json:"updated_ts,omitempty"`
}

// TaskManualUpdateDTO Partial manual edit — only supplied fields change. “assignee“ is {"kind":"member","member_id":…} or {"kind":"outsource","runtime":"claude|codex","model":…,"effort":…,"copies":N,"machine":…}; {} unsets it. Outsource runtime absent means claude; “copies“ MUST be a number >= 0 (0 = 無限 — unlimited per-type parallel copies; absent = 1); “machine“ MUST be a non-blank machine id when present, and must resolve to a real machine ("auto" is rejected — it names no machine); absent leaves the type without a placement.
type TaskManualUpdateDTO struct {
	Assignee    *map[string]interface{} `json:"assignee,omitempty"`
	DisplayName *string                 `json:"display_name,omitempty"`
	Fields      *[]TaskManualFieldDTO   `json:"fields,omitempty"`
	Learnings   *string                 `json:"learnings,omitempty"`
	Purpose     *string                 `json:"purpose,omitempty"`
	SopMd       *string                 `json:"sop_md,omitempty"`
}

// TaskMarkDuplicateDTO Mark a task duplicated (MCP “mark_duplicate“), pointing at the ORIGINAL it duplicates. The caller must be the task's executor (owner/admin may act on any task); “duplicated“ is a terminal status alongside done/terminated, reachable only through this dedicated action (task status is otherwise derived from the steps and is never agent-reported). “duplicate_of“ is required and must name an EXISTING task that is not this one (409 self-reference) and is not itself already “duplicated“ (409 — point at the FINAL original, the server never chases a chain); a task already pointed at as an original cannot itself be marked duplicated (409). An already-terminal task is a 409. T-74f8 交棒閘 (third door): “duplicated“ is terminal, so this closes the task; it is never refused. A duplicate's ball is on the ORIGINAL by construction, so the server records that itself — a cross-executor task marked duplicate lands “handoff='follow_up'“ with “handoff_task_id“ = “duplicate_of“. No task_dep edge is added (the original is not blocked by its duplicate).
type TaskMarkDuplicateDTO struct {
	DuplicateOf string `json:"duplicate_of"`
}

// TaskMessageDTO The task-card message box (owner or admin agent → executor; floor admin_agent since T-6020): the server posts one ordinary chat message to the task's executor with the task context auto-attached in “meta“ ({task_id, task_title, task_type}). An unassigned executor is a 409.
type TaskMessageDTO struct {
	Attachments *[]ChatAttachmentInputDTO `json:"attachments,omitempty"`
	Body        *string                   `json:"body,omitempty"`
}

// TaskPlanDTO Submit/replace the workflow plan (MCP “submit_plan“): replaces every non-preserved step wholesale. Kept ahead of the fresh plan, in original order: done steps, already-superseded history, and steps whose latest bound reply card is answered/expired — those freeze into the “superseded“ terminal state (T-1aea) unless the fresh plan re-lists them by name (then the live row continues — no copy). Steps holding a still-waiting card are replaced like any other. New steps open “pending“. T-74f8 交棒閘 (second door): a plan is a step-set write and the task status is DERIVED from the step set, so a plan that leaves EVERY step done CLOSES the task — the same irreversible close the final step report performs. If that task's creator is not its executor and no handover is declared or already real, the replan is refused with 422 BEFORE anything is written (the plan stays fully editable). A plan carries no handoff field, so the way out is to hand over first: create the successor task and point its “blocked_by“ at this task (the gate then stands aside by itself), or keep one unfinished step and declare the handover on the “update_step_status“ report that closes it. A replan that still leaves work in the plan is never gated.
type TaskPlanDTO struct {
	Steps []TaskPlanStepDTO `json:"steps"`
}

// TaskPlanReceiptDTO Bounded receipt returned after submit_plan (T-a98d). The caller just sent the plan, so echoing it back was the least useful payload on the wire; these counters are what it could not know — how many steps the STORED timeline holds (kept done/superseded history included) and where the leaf progress landed. Fetch GET /api/tasks/{task_id} for the step rows themselves.
type TaskPlanReceiptDTO struct {
	ProgressDone  int    `json:"progress_done"`
	ProgressTotal int    `json:"progress_total"`
	StepsTotal    int    `json:"steps_total"`
	TaskId        string `json:"task_id"`
}

// TaskPlanStepDTO One planned workflow node of a submit_plan body. Parallel (fork-join) shape is validated at the write seam (400 otherwise): steps sharing a non-empty “parallel_group“ must sit consecutively and number at least two, and a gate step must not carry a “parallel_group“ (put the gate after the group's join step). Contiguity is checked over the resulting timeline, i.e. including the kept done prefix.
type TaskPlanStepDTO struct {
	Dod           string  `json:"dod"`
	IsGate        *bool   `json:"is_gate,omitempty"`
	Name          string  `json:"name"`
	ParallelGroup *string `json:"parallel_group,omitempty"`
}

// TaskPriorityReceiptDTO Bounded receipt returned after set_task_priority (T-a98d). “frozen_by“ rides along because the write DERIVES it (stamped on the way into frozen, cleared on the way out), so it is the part the caller cannot predict. Fetch GET /api/tasks/{task_id} when full task detail is needed.
type TaskPriorityReceiptDTO struct {
	FrozenBy string `json:"frozen_by"`
	Priority string `json:"priority"`
	TaskId   string `json:"task_id"`
}

// TaskPriorityUpdateDTO Priority change: “high“ | “mid“ | “low“ | “frozen“ (freeze/unfreeze ride the same knob — SPEC §3.3). The owner and an admin agent may set any value on any task; the task's own executor may set any value on their task — frozen INCLUDED, and the clear of a frozen task is admitted for exactly the same set (T-6020: whoever may freeze may unfreeze). A caller who is none of the three is a flat 403.
type TaskPriorityUpdateDTO struct {
	Priority string `json:"priority"`
}

// TaskReassignDTO Reassign request (“POST /api/tasks/{task_id}/reassign“ / MCP “reassign_task“): the new executor target plus an optional handover note written as the task's latest durable handover context. Member targets also receive the existing notification chat message.
type TaskReassignDTO struct {
	Note *string `json:"note,omitempty"`

	// Target The reassignment target. ``kind='member'`` requires ``member_id`` — an ACTIVE roster member below the warden layer (a warden or an inactive/unknown member is a 400). ``kind='outsource'`` lands the task unassigned for the scheduler to spawn a fresh worker under the global parallel cap (no owner-approval card; T-35e0): ``runtime`` is claude/codex (absent = claude); ``model`` is the worker's model (blank/absent = selected-runtime default); ``effort`` is low|medium|high|max (absent = ``medium``); ``machine`` is the machine the worker boots on — a machine id that must resolve; absent inherits (see below). An offline machine is NOT substituted at spawn time: nothing is dispatched and the reason is recorded on the worker. Any of ``runtime``/``model``/``effort``/``machine`` that is OMITTED is INHERITED: a TYPED task takes the type manual's outsource assignee, a FREE (ad-hoc) task takes the DISPATCHING member's own runtime/model/effort and the machine it is itself pinned to (發包 without a spec means "one like me"). ``runtime`` and ``model`` inherit together — an inherited model is kept only under the runtime it belongs to, else the runtime's default model applies. ``effort`` falls back to ``medium``. ``machine`` has NO final fallback: when nothing names one the task carries no placement and no worker is started until one is chosen. The resolved spec is persisted on the task row and re-read on handover/rebirth, never re-derived.
	Target TaskReassignTargetDTO `json:"target"`
}

// TaskReassignTargetDTO The reassignment target. “kind='member'“ requires “member_id“ — an ACTIVE roster member below the warden layer (a warden or an inactive/unknown member is a 400). “kind='outsource'“ lands the task unassigned for the scheduler to spawn a fresh worker under the global parallel cap (no owner-approval card; T-35e0): “runtime“ is claude/codex (absent = claude); “model“ is the worker's model (blank/absent = selected-runtime default); “effort“ is low|medium|high|max (absent = “medium“); “machine“ is the machine the worker boots on — a machine id that must resolve; absent inherits (see below). An offline machine is NOT substituted at spawn time: nothing is dispatched and the reason is recorded on the worker. Any of “runtime“/“model“/“effort“/“machine“ that is OMITTED is INHERITED: a TYPED task takes the type manual's outsource assignee, a FREE (ad-hoc) task takes the DISPATCHING member's own runtime/model/effort and the machine it is itself pinned to (發包 without a spec means "one like me"). “runtime“ and “model“ inherit together — an inherited model is kept only under the runtime it belongs to, else the runtime's default model applies. “effort“ falls back to “medium“. “machine“ has NO final fallback: when nothing names one the task carries no placement and no worker is started until one is chosen. The resolved spec is persisted on the task row and re-read on handover/rebirth, never re-derived.
type TaskReassignTargetDTO struct {
	Effort   *string `json:"effort,omitempty"`
	Kind     string  `json:"kind"`
	Machine  *string `json:"machine,omitempty"`
	MemberId *string `json:"member_id,omitempty"`
	Model    *string `json:"model,omitempty"`

	// Runtime Outsource runtime; null/absent defaults to ``claude``.
	Runtime *AgentRuntime `json:"runtime,omitempty"`
}

// TaskRefDTO The light task reference a reply card carries when it was armed from a task gate (請示 → 任務 jump, SPEC §3.6): id (the jump anchor), the type, and the title.
type TaskRefDTO struct {
	Id      string  `json:"id"`
	Title   *string `json:"title,omitempty"`
	TypeKey *string `json:"type_key,omitempty"`
}

// TaskSopPatchDTO Anchor-addressed PATCH of a type's SOP (MCP “patch_task_sop“ — the sop_md twin of “patch_task_learnings“): “{edits: [{old, new}], allow_shrink?}“. It exists to stop CONCURRENT OVERWRITE: the only sop_md write face was “update_task_manual.sop_md“, a whole-doc replace, so a caller holding a stale copy silently deletes whatever landed in between — and because the stale copy is usually the LONGER one, the shrink guard never fires and the loss carries no signal at all. An anchor patch cannot express that write: each non-empty “old“ must match the current sop_md EXACTLY ONCE, so a concurrent write that moved or duplicated the anchor turns the batch into a visible refusal. ATOMIC — edits apply sequentially to an in-memory copy and any failing anchor (absent or ambiguous “old“) rejects the ENTIRE batch with a flat 400 and ZERO writes. “allow_shrink“ (default false) must be set explicitly for a patch that empties the doc or shrinks it to under a tenth of its size — the r-76 wipe-guard posture.
type TaskSopPatchDTO struct {
	AllowShrink *bool            `json:"allow_shrink,omitempty"`
	Edits       []LessonsEditDTO `json:"edits"`
}

// TaskSopPatchResultDTO Receipt of a task-SOP PATCH (MCP “patch_task_sop“). “size_chars“ (CHARACTERS — Unicode code points, the SAME unit as the “doc.cap_chars.manual_sop“ cap the write is judged against) and “sha256“ (hex) are lightweight verification anchors over the RESULTING sop_md text, so the caller can confirm the write landed without re-reading the full doc. “applied_edits“ counts the edits that changed the text THEY were handed (a no-op append/replace does not count), so "0 applied" is expressible and a silent no-op cannot masquerade as success. It is not a report on whether the document ended up different from where it started: a batch whose edits undo one another (“anchor → middle“ then “middle → anchor“) reports the full count over a sop_md that never moved, and nothing is written in that case. To decide whether the doc actually changed, compare “sha256“ against the value you held before the call.
type TaskSopPatchResultDTO struct {
	AppliedEdits *int `json:"applied_edits,omitempty"`

	// CapChars The document size cap in force when this write was judged, in CHARACTERS (the doc.cap_chars.manual_sop setting — this face only ever writes sop_md). Returned so a caller can see its remaining budget without a second request — the cap is adjustable and agents cannot read the settings surface.
	CapChars *int    `json:"cap_chars,omitempty"`
	Sha256   *string `json:"sha256,omitempty"`

	// SizeChars Size of the RESULTING document in CHARACTERS (Unicode code points) — the same unit as cap_chars.
	SizeChars *int    `json:"size_chars,omitempty"`
	TypeKey   *string `json:"type_key,omitempty"`
}

// TaskStepDTO One workflow node on the task timeline. Every row is one progress leaf (parallel items are separate rows sharing “parallel_group“). A parallel stage is CONSECUTIVE rows sharing a non-empty “parallel_group“ — submit_plan refuses (400) split groups, one-lane groups and gates inside a group, so stored plans always fold cleanly. “status“ is the closed set “pending“ | “in_progress“ | “waiting_owner“ | “done“ | “superseded“. “done“ and “superseded“ are the step's terminal states: “superseded“ (T-1aea) is stamped by submit_plan alone — a replan freezes a step whose latest bound reply card was already answered/expired as kept history (original order, ahead of the fresh plan) unless the fresh plan re-lists the node by name; a superseded row counts toward neither “progress_done“ nor “progress_total“, is never the current node, is not agent-reportable and cannot be re-armed; its “finished_ts“ is the freeze moment. Gate projection: “is_gate“ with an empty “reply_card_id“ is the ANNOUNCED (dashed) gate; a non-empty “reply_card_id“ is a step carrying a live reply card — an ARMED gate, or a plain step a “create_reply_card“ ask named in its “linked_task“. “reply_card_id“ always points at the LATEST bound card and persists after the step finishes (the permanent approval mark).
type TaskStepDTO struct {
	Dod        *string  `json:"dod,omitempty"`
	FinishedTs *float64 `json:"finished_ts,omitempty"`
	Id         string   `json:"id"`
	IsGate     *bool    `json:"is_gate,omitempty"`
	Name       *string  `json:"name,omitempty"`

	// Note T-cc3e — the step's free-text working note: what this step got to and what comes next. The GENERAL-PURPOSE note the handover SOP has always told agents to write ("把還在進行中的工作寫回 task step note") and which, until this field existed, had nowhere to land. Writable in ANY step status via POST /api/tasks/{task_id}/steps/{step_id}/note (MCP ``update_step_note``) — unlike ``waiting_reason``, which is bound to waiting_external and cleared on leaving it, and unlike the handoff fields, which are read only on the report that closes the task. Division of labour with the task-level ``description``: the description says WHAT THIS TASK IS (scope, origin, acceptance — stable); the step note says WHERE THIS STEP IS RIGHT NOW (volatile, rewritten as work moves, read by the next session after a handover). Last write wins, wholesale — it is a current-state note, not an append-only log.
	Note *string `json:"note,omitempty"`

	// NoteCapChars The ceiling the step-note write faces enforce, REPORTED here so the room left can be computed from a read. Until T-6bd2 the step note was the one capped document whose remaining room appeared on no read at all — neither this view nor the wholesale write receipt carried it — so an agent only ever learned the number from the 400 that refused its write, which is both the latest possible moment and the cell that is hit most often. T-6bd2 reports the ceiling and does not move it. Additive-optional.
	NoteCapChars *int `json:"note_cap_chars,omitempty"`

	// NoteSizeChars The step note's current size in CHARACTERS. Additive-optional (T-6bd2).
	NoteSizeChars *int    `json:"note_size_chars,omitempty"`
	OrderIdx      int     `json:"order_idx"`
	ParallelGroup *string `json:"parallel_group,omitempty"`
	ReplyCardId   *string `json:"reply_card_id,omitempty"`

	// ReplyCardStatus Read-time join: the CURRENT status (``waiting`` | ``answered``) of the reply card bound to this step (``reply_card_id``); ``""`` when the step carries no card. Lets the task-embedded card (TaskReplyCard) decide AT MOUNT whether to load eagerly (waiting — the live ask / the H4 answered-awaiting-pickup transitional) or lazily (answered — collapsed one-line summary, fetch on expand) WITHOUT a per-card GET, and lets the board derive the H4 badge without the child round-trip. NOT stored — computed each read from the card's live status.
	ReplyCardStatus *string  `json:"reply_card_status,omitempty"`
	StartedTs       *float64 `json:"started_ts,omitempty"`
	Status          string   `json:"status"`
	TaskId          string   `json:"task_id"`
	WaitingReason   *string  `json:"waiting_reason,omitempty"`
}

// TaskStepNotePatchDTO Anchor-addressed PATCH of one step's working note (MCP “patch_step_note“): “{edits: [{old, new}], allow_shrink?}“. It exists to stop CONCURRENT OVERWRITE: “update_step_note“ is a whole-doc replace, so a caller that read the note earlier and writes it back silently deletes whatever a second writer added in between — and because the stale copy is usually the LONGER one, no shrink guard fires and the loss carries no signal at all. An anchor patch cannot express that write: each non-empty “old“ must match the current note EXACTLY ONCE, so a concurrent write that moved or duplicated the anchor turns the batch into a refusal. ATOMIC — edits apply sequentially to an in-memory copy and any failing anchor (absent or ambiguous “old“) rejects the ENTIRE batch with a flat 400 and ZERO writes; an empty “old“ appends “new“. “allow_shrink“ (default false) must be set explicitly for a patch that empties the note or shrinks it to under a tenth of its size — the r-76 wipe-guard posture; use “update_step_note“ for an honest wholesale rewrite.
type TaskStepNotePatchDTO struct {
	AllowShrink *bool            `json:"allow_shrink,omitempty"`
	Edits       []LessonsEditDTO `json:"edits"`
}

// TaskStepNotePatchResultDTO Receipt of a step-note PATCH (MCP “patch_step_note“). Echoes the note as STORED — the same posture as the wholesale receipt, since the whole point of the field is that a later session reads it back — plus “applied_edits“ (the edits that changed the text THEY were handed, so "0 applied" is expressible and a silent no-op cannot masquerade as success — it is not a report on whether the note ended up different from where it started: a batch whose edits undo one another (“anchor → middle“ then “middle → anchor“) reports the full count over a note that never moved, and in that case the stored note, the task's “updated_ts“ and every open cockpit card are left exactly as they stood, so compare “sha256“ against the value you held before the call to decide that) and “size_chars“/“cap_chars“/“sha256“ verification anchors over the resulting note. “size_chars“ and “cap_chars“ are CHARACTERS (Unicode code points), the unit the note's limit is enforced in.
type TaskStepNotePatchResultDTO struct {
	AppliedEdits *int `json:"applied_edits,omitempty"`

	// CapChars The step-note ceiling this write was judged against, in CHARACTERS — the same limit ``update_step_note`` enforces, shared with the task-level handover note. NOT a setting: unlike the ``cap_chars`` on the manual patch receipts (which report the adjustable ``doc.cap_chars.*`` values), this one is a server CONSTANT and no settings key moves it. Same field name, different source — do not read one as evidence about the other.
	CapChars   *int    `json:"cap_chars,omitempty"`
	Note       string  `json:"note"`
	Sha256     *string `json:"sha256,omitempty"`
	SizeChars  *int    `json:"size_chars,omitempty"`
	StepId     string  `json:"step_id"`
	StepStatus string  `json:"step_status"`
	TaskId     string  `json:"task_id"`
}

// TaskStepNoteReceiptDTO Bounded receipt returned after writing one step's working note (T-cc3e). Echoes the note as STORED, so the caller can confirm what actually landed without a follow-up GET — the point of the field is that the next session reads it back, so the write must be verifiable at the write. Fetch GET /api/tasks/{task_id} when full task detail is needed.
type TaskStepNoteReceiptDTO struct {
	// CapChars The step-note ceiling in force; same value and same meaning as on the patch receipt. Additive-optional (T-6bd2).
	CapChars *int   `json:"cap_chars,omitempty"`
	Note     string `json:"note"`

	// SizeChars The stored note's size in CHARACTERS. Additive-optional (T-6bd2): the PATCH receipt has carried this pair since T-1667 and this wholesale one did not, so the writer that replaces a note outright — the common case, and the one that has just deleted the previous session's hand-off to make room — was the one writer told nothing about the room left.
	SizeChars  *int   `json:"size_chars,omitempty"`
	StepId     string `json:"step_id"`
	StepStatus string `json:"step_status"`
	TaskId     string `json:"task_id"`
}

// TaskStepNoteUpdateDTO Write one step's working note (MCP “update_step_note“, T-cc3e). WHAT TO WRITE — three things, then stop: (1) STATE — one sentence on where this step actually got to; (2) NEXT — one sentence on what whoever takes over does next; (3) EVIDENCE POINTERS — version ids, file and log paths, what you verified YOURSELF versus what you are taking on someone's word, and the limits of what was NOT done. Long narrative does not live here: reasoning and scope belong in the task description, reports and diffs belong on the task as artifacts. The note is the current state — not a report, not an append-only log. Accepted in ANY STEP status — pending, in_progress, waiting_owner, waiting_external, done and superseded alike, for as long as the TASK itself is open — because the note records where the work stands, which is orthogonal to the state machine; that generality is the whole point, since the previous two note-shaped fields were each locked to one moment (“waiting_reason“ to waiting_external, the handoff fields to the closing report). Deliberately its OWN endpoint and its OWN tool rather than another parameter on update_step_status (charter §14 intent-per-tool): writing a note is a different intent from reporting a transition, and one field with two write paths is exactly the ambiguity this ticket exists to remove. The write is wholesale — the body's “note“ replaces whatever was there; sending “""“ clears it.
type TaskStepNoteUpdateDTO struct {
	Note string `json:"note"`
}

// TaskStepStatusReceiptDTO Bounded receipt returned after updating one task step. Fetch GET /api/tasks/{task_id} when full task detail is needed.
type TaskStepStatusReceiptDTO struct {
	ClosedTs      *float64 `json:"closed_ts"`
	ProgressDone  int      `json:"progress_done"`
	ProgressTotal int      `json:"progress_total"`
	StepId        string   `json:"step_id"`
	StepStatus    string   `json:"step_status"`
	TaskId        string   `json:"task_id"`
	TaskStatus    string   `json:"task_status"`
	WaitingReason string   `json:"waiting_reason"`
}

// TaskStepStatusUpdateDTO Agent-reported step status (MCP “update_step_status“): “pending“ → “in_progress“ → “done“ — “waiting_owner“ is NOT agent-reportable on either side (a step enters it only by opening a reply card: create_reply_card carrying an explicit “linked_task“ {task_id, step_id}, and leaves it only when that card is answered, where the server restores in_progress), so reporting “waiting_owner“ is a 400 and a move out of it is a 409; other illegal transitions are a 409. “superseded“ is likewise not the agent's lever: the server freezes a replaced answered-card step itself on submit_plan (T-1aea), so reporting “superseded“ is a 400 and no report moves a step out of it (409 — terminal). T-74f8 交棒閘: if applying this report would CLOSE the task (every step done) and the task's creator is not its executor, the server refuses the report with a 422 unless the ball's destination is declared IN THIS SAME CALL — “handoff='return_to_creator'“ (the server mints a durable follow-up task on the creator, blocked by this one), “handoff='follow_up'“ + “handoff_task_id“ (the server attaches this task to that successor as a dependency), or “handoff='none'“ + “handoff_note“ (an explicit, recorded end of the line). The gate stands aside when a non-terminal task already depends on this one (the handover is already real). It refuses BEFORE any row is written, because a closed task can never be replanned (submit_plan turns into a permanent 409) — after the close there is nothing left to answer with.
type TaskStepStatusUpdateDTO struct {
	// Handoff Where the ball goes when this report closes the task: ``return_to_creator`` | ``follow_up`` | ``none``. Read only on the report that would close the task.
	Handoff *string `json:"handoff,omitempty"`

	// HandoffNote The handover sentence. REQUIRED for ``handoff='none'`` — an un-reasoned "nothing follows" is indistinguishable from forgetting, and the note is the only record that a decision was made.
	HandoffNote *string `json:"handoff_note,omitempty"`

	// HandoffTaskId The successor task id. REQUIRED for ``handoff='follow_up'``; the server adds this task to that successor's blocked_by list.
	HandoffTaskId *string `json:"handoff_task_id,omitempty"`
	Status        string  `json:"status"`
	WaitingReason *string `json:"waiting_reason,omitempty"`
}

// TaskTitleDTO Correct one task's title in place (T-2ebe). 🔴 SINCE T-646a THIS ROUTE IS NO LONGER AN MCP TOOL: the agent-facing tool is “update_task“, which writes this same field through the same code (updateTaskText). The route stays on the HTTP surface for the cockpit and any existing client, and its behaviour here is unchanged. PARTIAL update in “TaskDescriptionDTO“'s shape: the ONLY field is “title“, omitting it is a legal no-op that versions nothing, and unknown keys are refused (“additionalProperties: false“) so a caller who reaches for “name“ or “summary“ is told rather than ignored. ONE DELIBERATE DIFFERENCE FROM THE DESCRIPTION TWIN, and it is a difference in kind rather than an oversight: an explicit blank (“""“ or whitespace-only) is REFUSED with 400 instead of clearing the field. “create_task“ has always refused a blank title on the same terms, and an edit door looser than the create door would let a caller reach a state the create door forbids — a task whose only cell on the task list is empty, which is precisely the surface this capability exists to keep true. The value is trimmed of surrounding whitespace before it is stored, again matching create. The write is wholesale within that one field; there is no append form.
type TaskTitleDTO struct {
	Title *string `json:"title,omitempty"`
}

// ThemeBundleDTO One owner-authored theme colour bundle (T-16a1 P2). `id` is a client-generated stable slug (`^[a-z0-9][a-z0-9-]{1,63}$`), unique within the owner's set and never a built-in name (`office` / `xian`). `name` is the display label (trimmed, 1..80 runes). `colors` maps `--color-*` token names — each MUST be a token defined in styles/theme.css — to CONCRETE colour values (hex / rgb() / rgba() / hsl() / hsla() / transparent only; no var(), no color-mix(), no arbitrary CSS). 1..200 pairs. The server 422s any bundle that violates the shape, the token whitelist, or the colour grammar. `wording` (optional, T-16a1 P3) carries per-language message-key text overrides; see its own description. `fonts` (optional, T-16a1 P4) carries font-family choices; see its own description.
type ThemeBundleDTO struct {
	// Avatars Optional per-role avatar images (T-16a1 P5; extended per role in T-ea81). Keys are the closed set `member` (一般正職 member) / `outsource` (外包 outsource worker) / `owner` (the human CEO / owner) / `assistant` (a member whose role is `assistant`, e.g. Mira). Each value is an EMBEDDED image encoded as a base64 `data:` URI so the image travels inside the bundle on export/import. The value is NOT arbitrary: only a `data:image/<mime>;base64,<...>` URI whose mime is a whitelisted RASTER format (`image/png` / `image/jpeg` / `image/webp`) is accepted. SVG (`image/svg+xml`) is REJECTED (it can carry script/onload — XSS). The base64 must decode, the decoded byte size is capped (<=64 KiB) and the string length capped, and the leading magic bytes must match the declared mime (PNG `89 50 4E 47`, JPEG `FF D8 FF`, WEBP `RIFF....WEBP`) — a value that declares one mime but carries another is rejected. Absent = that role falls back to the built-in avatar glyph (office never degrades). The server 422s any avatars that violates the key set, the mime whitelist, the size caps, the base64, or the magic-byte check.
	Avatars *map[string]string `json:"avatars,omitempty"`

	// BackgroundModes Optional per-zone DISPLAY MODE for the images in `backgrounds` (T-081b). Same CLOSED zone-key set as `backgrounds` (today: `canvas`); each value is one of a CLOSED set of three: `tile` — repeat the image in both axes over the whole canvas (the ONLY behaviour before this field existed, and the default for any zone this map omits, so an older bundle renders identically); `sides` — do NOT repeat at all: pin ONE copy of the image against the LEFT viewport edge and one against the RIGHT, both at natural size, aligned to the viewport bottom, with `--color-bg` filling whatever the image does not reach; `cover` — ONE copy scaled (`background-size: cover`) to fill the whole viewport, centred. `sides` exists for art that reads as a pair of standing objects (e.g. a tree either side) rather than a texture; the product does NOT mirror the right-hand copy — a theme wanting left/right symmetry bakes it into the image (owner 2026-07-27). `sides` and `cover` are pinned to the VIEWPORT (`background-attachment: fixed`) because the canvas background otherwise scrolls with the document, which would bring a second copy into view down a long page. `cover` is only VISIBLE where the theme also gives the chrome zone colours (`--color-topbar-bg` / `--color-nav-bg` / `--color-main-bg`) translucent values — the colour grammar already admits `#RRGGBBAA` and `rgba()` — and that is also where its risk lives: those zones sit under text, so the image's contrast against that text is the theme's own responsibility (owner accepted this trade-off on 2026-07-27). A mode for a zone that carries no image is a 422 (a mode alone paints nothing, so it is a mistake worth naming rather than ignoring). Absent = every zone tiles, exactly as before this field existed. NOTE both modes are invisible at viewport widths where the content column leaves no gutter (phones, narrow windows) — that is a property of the outer canvas, not of the mode.
	BackgroundModes *map[string]string `json:"backgroundModes,omitempty"`

	// Backgrounds Optional background images for the cockpit's chrome (T-081b). Keys are a CLOSED set holding exactly one zone today: `canvas` — the OUTERMOST canvas, i.e. the page background behind the centred content column. In `tile` / `sides` mode only the area BESIDE that column shows it, which is nothing on a phone, in a narrow window, or in the wide layout (all of which leave no side gutter); in `cover` mode the image fills the viewport and shows through wherever the theme gives the chrome zone colours translucent values. The zone tokens above it (`--color-topbar-bg` / `--color-nav-bg` / `--color-main-bg`) deliberately take NO image: they sit under text, and text over a busy pattern has no readability guarantee. Each value is an EMBEDDED image encoded as a base64 `data:` URI laid on top of the solid `--color-bg`, which still shows through wherever the image does not cover; HOW it is laid down is `backgroundModes` (default `tile`). Same strict image gate as `avatars`: only a `data:image/<mime>;base64,<...>` URI whose mime is a whitelisted RASTER format (`image/png` / `image/jpeg` / `image/webp`) is accepted; SVG (`image/svg+xml`) is REJECTED (script/onload XSS); the base64 must decode, and the leading magic bytes must match the declared mime (PNG `89 50 4E 47`, JPEG `FF D8 FF`, WEBP `RIFF....WEBP`). The SIZE caps are the one place backgrounds differ from `avatars`: the decoded byte size is capped at <=512 KiB (with the raw data-URI string capped above the base64-inflated form of that), NOT the <=64 KiB that applies to `avatars` / `logo` / `navIcons`. A background is stretched or tiled across the whole viewport, where the glyph-sized 64 KiB cap read as visibly blurry; that cap — and the T-081b ruling that a background must never exceed it — was overturned by the owner on 2026-08-03, and the small-glyph fields keep 64 KiB. Absent = the outer canvas is the plain `--color-bg` colour, exactly as before this field existed. The server 422s any backgrounds that violates the key set, the mime whitelist, the size caps, the base64, or the magic-byte check.
	Backgrounds *map[string]string `json:"backgrounds,omitempty"`
	Colors      map[string]string  `json:"colors"`

	// Fonts Optional font-family choices (T-16a1 P4). Maps a `--font-*` token name (`--font-sans` / `--font-title` only) to a font-family stack string. The value is NOT an arbitrary string: it must be one of a small CLOSED allowlist of safe, built-in font-family stacks (themeFonts.source.json — the same set the theme editor's font dropdown offers); no url(), no @font-face, no external font, no CSS structure characters. Absent = the theme keeps the default fonts. The server 422s any fonts that violates the token set or the safe-family allowlist.
	Fonts *map[string]string `json:"fonts,omitempty"`
	Id    string             `json:"id"`

	// Logo Optional studio logo image (T-ea81). A single EMBEDDED image encoded as a base64 `data:` URI that replaces the built-in logo mark shown in the top bar. Same strict image gate as `avatars`: only a `data:image/<mime>;base64,<...>` URI whose mime is a whitelisted RASTER format (`image/png` / `image/jpeg` / `image/webp`) is accepted; SVG (`image/svg+xml`) is REJECTED (script/onload XSS); the base64 must decode, the decoded byte size is capped (<=64 KiB) and the string length capped, and the leading magic bytes must match the declared mime (PNG `89 50 4E 47`, JPEG `FF D8 FF`, WEBP `RIFF....WEBP`). Absent = the built-in logo mark is used (office never degrades). The server 422s any logo that violates the mime whitelist, the size caps, the base64, or the magic-byte check.
	Logo *string `json:"logo,omitempty"`
	Name string  `json:"name"`

	// NavIcons Optional per-tab navigation icon images (T-ea81). Keys are the closed set of the five nav tabs `office` (辦公室) / `replies` (請示) / `tasks` (任務) / `monitor` (監控) / `guide` (使用說明); each value is an EMBEDDED image encoded as a base64 `data:` URI that replaces that tab's built-in icon. Same strict image gate as `avatars`: only a `data:image/<mime>;base64,<...>` URI whose mime is a whitelisted RASTER format (`image/png` / `image/jpeg` / `image/webp`) is accepted; SVG (`image/svg+xml`) is REJECTED (script/onload XSS); the base64 must decode, the decoded byte size is capped (<=64 KiB) and the string length capped, and the leading magic bytes must match the declared mime (PNG `89 50 4E 47`, JPEG `FF D8 FF`, WEBP `RIFF....WEBP`). Absent = that tab falls back to its built-in icon (office never degrades). The server 422s any navIcons that violates the key set, the mime whitelist, the size caps, the base64, or the magic-byte check.
	NavIcons *map[string]string `json:"navIcons,omitempty"`

	// Wording Optional per-language wording overrides (T-16a1 P3). Outer key = UI language (`zh` / `en` only); inner map = an i18n message-key (an internal code path such as `nav.tasks`, drawn from the generated messageKeys whitelist) -> the owner's replacement PLAIN TEXT. Values are plain text only (trimmed, <=200 runes, control chars / newlines rejected, per-language entry count capped); no HTML/CSS. Absent = no overrides. The server 422s any wording that violates the language set or the value rules. A code OUTSIDE the messageKeys whitelist is NOT a 422: it is DROPPED from the overlay and the request succeeds, so the response echoes a pruned `wording` and only the surviving codes are stored (an already-imported theme pack stays usable when the whitelist shrinks; the accepted cost is that a typo'd code silently does nothing).
	Wording *map[string]map[string]string `json:"wording,omitempty"`
}

