// outcome ("restarting" — the new binary is already verified and swapped
// in place; the process re-execs right after this response) and
// `target_version` the GitHub release tag being installed. The endpoint
// fires only on an explicit owner/admin-agent trigger; the OPT-IN `updater_auto_update`
// setting runs the same verified body unattended in the background.
type UpgradeResultDTO struct {
	Status        string `json:"status"`
	TargetVersion string `json:"target_version"`
}

// VersionDTO Build identity: app version, git sha, and the MCP catalog hash (M1 §3.9).
//
// `version` is the single human-facing version identity: an OFFICIAL package
// (bin/release) is stamped with its GitHub Release tag; a self-build keeps the
// honest "0.0.0" (the UI then falls back to git_sha + git_time as the build
// label).
//
// `git_time` is the commit time of the running `git_sha` (strict ISO-8601), or
// None when unavailable (release tarball / no git).
//
// `update_available` drives the software-update card: the server periodically
// asks GitHub Releases (repo pkyosx/OffiCraft, anonymous) for the newest
// published release (cached, refreshed in the background — unreachable GitHub
// NEVER slows this probe) and reports honestly: True iff the newest admissible
// release tag is STRICTLY NEWER than the running `version` under semver
// ordering (`latest_version` then carries the tag); running >= latest reads
// False, and a version label that does not parse as semver on either side
// reads False (with a server-side log warning) — never a prompt. A
// self-build's "0.0.0" sorts below any published release and therefore
// still prompts. Prereleases are admitted only when the
// `updater_receive_beta` setting is on.
//
// `update_checked_ok_at` is WHEN that check last SUCCEEDED (RFC3339, UTC).
// It is the freshness of `update_available`, which on its own cannot tell
// "checked a minute ago, nothing newer" apart from "the check has never once
// succeeded" (GitHub unreachable, rate-limited, or never run) — both answer
// False. A FAILED check NEVER moves it; absent/None means no check has ever
// succeeded under the current channel (a channel flip resets it). It is
// deliberately NOT the check cache's TTL anchor — that stays the last
// ATTEMPT, so an unreachable GitHub is retried once per TTL, not hammered.
type VersionDTO struct {
	CatalogHash       string  `json:"catalog_hash"`
	GitSha            string  `json:"git_sha"`
	GitTime           *string `json:"git_time,omitempty"`
	LatestVersion     *string `json:"latest_version,omitempty"`
	UpdateAvailable   *bool   `json:"update_available,omitempty"`
	UpdateCheckedOkAt *string `json:"update_checked_ok_at,omitempty"`
	Version           string  `json:"version"`
}

// WebhookCreateDTO Create one webhook endpoint on a member (M4 §1). `endpoint_id` is REQUIRED, immutable after creation, per-member-unique, and restricted to letters/digits/`_`/`-` (422 otherwise; 409 on a duplicate id). `purpose` is optional editable free text. The server mints the opaque `token` and returns it once on the WebhookEndpointDTO.
type WebhookCreateDTO struct {
	EndpointId string `json:"endpoint_id"`

	// Platform Verification preset for the public `/in` inlet. Omit or `generic` = current behaviour (URL token only). `slack`/`github` = the server applies that platform's preset: the Slack url_verification challenge handshake and X-Slack-Signature HMAC, or the GitHub X-Hub-Signature-256 HMAC. Immutable after creation.
	Platform *WebhookCreateDTOPlatform `json:"platform,omitempty"`
	Purpose  *string                   `json:"purpose,omitempty"`

	// SigningSecret Write-only shared secret for HMAC verification (accepted on create, NEVER echoed back). Slack: the Signing Secret from the app's Basic Information page. GitHub: the secret set when creating the webhook. REQUIRED when `platform` is `slack` or `github`; ignored for `generic`.
	SigningSecret *string `json:"signing_secret,omitempty"`
}

// WebhookCreateDTOPlatform Verification preset for the public `/in` inlet. Omit or `generic` = current behaviour (URL token only). `slack`/`github` = the server applies that platform's preset: the Slack url_verification challenge handshake and X-Slack-Signature HMAC, or the GitHub X-Hub-Signature-256 HMAC. Immutable after creation.
type WebhookCreateDTOPlatform string

// WebhookEndpointDTO API representation of one webhook_endpoint (M4 回呼端點, §1). Carries the durable fields the member-detail panel renders. The `token` is the opaque secret the public `/in` inlet identifies (member · endpoint · purpose) by; it rides THIS authenticated wire so the panel can compose + copy the callback URL (the UI masks it visually; copy yields the full URL). It is NEVER on any PUBLIC wire, and since T-5336 this operation requires the admin_agent floor, so a plain agent token cannot read it either. `endpoint_id` is the user-chosen, per-member-unique, immutable address key; `purpose` is editable free text; `status` is the enabled/disabled revocation toggle.
type WebhookEndpointDTO struct {
	CreatedTs float64 `json:"created_ts"`

	// DeliveredCount How many `/in` payloads passed verification AND were delivered to the member as a chat event. Owner-facing observability only — the public `/in` response never reflects any counter.
	DeliveredCount *int `json:"delivered_count,omitempty"`

	// DroppedCount How many `/in` calls that resolved to this token were silently discarded (failed verification, endpoint disabled, member gone). Calls with an unknown token have no endpoint to count against and are excluded by construction.
	DroppedCount *int   `json:"dropped_count,omitempty"`
	EndpointId   string `json:"endpoint_id"`

	// HasSigningSecret Whether this endpoint has a signing secret configured. The secret itself is NEVER echoed on any wire — not even masked; only this boolean is exposed (stricter than the `token` field, which the owner-facing panel still receives).
	HasSigningSecret *bool `json:"has_signing_secret,omitempty"`

	// LastDropReason Coarse classification of the most recent silent drop: `sig_failed` (Slack/GitHub signature or timestamp verification failed), `disabled` (endpoint was disabled), or `member_gone` (the bound member no longer resolves). Empty string when nothing was ever dropped.
	LastDropReason *string `json:"last_drop_reason,omitempty"`

	// LastReceivedTs Epoch seconds of the LAST `/in` request that resolved to this token — delivered, dropped, or challenge/ping alike. 0.0 when the endpoint has never been called.
	LastReceivedTs *float64 `json:"last_received_ts,omitempty"`

	// Platform The endpoint's verification preset (`generic`, `slack`, or `github`), fixed at creation.
	Platform *WebhookEndpointDTOPlatform `json:"platform,omitempty"`
	Purpose  string                      `json:"purpose"`
	Status   string                      `json:"status"`
	Token    string                      `json:"token"`
}

// WebhookEndpointDTOPlatform The endpoint's verification preset (`generic`, `slack`, or `github`), fixed at creation.
type WebhookEndpointDTOPlatform string

// WebhookRequestLogDTO One row of a webhook endpoint's /in debug ring buffer (GET /api/members/{member_id}/webhooks/{endpoint_id}/requests, newest first, at most 5 rows kept per endpoint). Records EVERY request /in resolved to the endpoint's token, whatever the outcome: `delivered` (verified payload landed as a chat), `dropped:sig_failed` / `dropped:disabled` / `dropped:member_gone` (silent drops with their coarse reason), `challenge` (the Slack url_verification handshake), `ping` (a verified GitHub ping). An unknown token has no endpoint to log against, by construction. `headers` is the JSON-serialised request header map (truncated at 4 KiB); `body` is the raw payload text (truncated at 16 KiB); `truncated` marks that either was cut. Governance-gated debug wire (requires=admin_agent since T-6020) - raw external payloads never ride any public or PLAIN-agent-facing surface, and the public /in response stays byte-identical regardless of logging.
type WebhookRequestLogDTO struct {
	Body      string  `json:"body"`
	Headers   string  `json:"headers"`
	Outcome   string  `json:"outcome"`
	Truncated bool    `json:"truncated"`
	Ts        float64 `json:"ts"`
}

// WebhookUpdateDTO Partial edit of a webhook endpoint (M4 §1). PATCH semantics — only supplied fields change. `status` flips the enabled/disabled revocation toggle (a value outside the set is a 422); `purpose` edits the description. `endpoint_id` is immutable and is NOT editable here.
type WebhookUpdateDTO struct {
	Purpose *string `json:"purpose,omitempty"`

	// SigningSecret Write-only. Supply to set or rotate the endpoint's signing secret (never echoed back). `platform` is immutable and cannot be changed here.
	SigningSecret *string `json:"signing_secret,omitempty"`
	Status        *string `json:"status,omitempty"`
}

// WorkerBootContextDTO The outsource worker's boot-context PREVIEW (GET /api/outsource-workers/{id}/boot-context, T-ba6b) — the worker twin of the member panel's /api/bootstrap preview. The server re-runs the SAME buildWorkerBootContext fold the spawn path uses. Since T-4595 that fold is the STAFF boot context minus the persona slot (系統互動 + 使用者自訂 + the boot sequence for the worker's own runtime); it carries no outsource-only document, no identity block, no bound task and no type manual, so it does not vary with them. HONEST: this is what the boot context would look like NOW — the seeds may have changed since spawn, and nothing is stored. Never carries a worker token.
type WorkerBootContextDTO struct {
	Context string `json:"context"`
}

// HandleListChatApiChatGetParams defines parameters for HandleListChatApiChatGet.
type HandleListChatApiChatGetParams struct {
	With     *string  `form:"with,omitempty" json:"with,omitempty"`
	Limit    *int     `form:"limit,omitempty" json:"limit,omitempty"`
	BeforeTs *float64 `form:"before_ts,omitempty" json:"before_ts,omitempty"`
	BeforeId *string  `form:"before_id,omitempty" json:"before_id,omitempty"`
	Peek     *string  `form:"peek,omitempty" json:"peek,omitempty"`

	// CallerOnly When true, return only messages involving both the verified caller and the optional `with` participant. Omitted or false preserves the existing participant-wide result.
	CallerOnly *bool `form:"caller_only,omitempty" json:"caller_only,omitempty"`

	// Ids RE-READ SPECIFIC MESSAGES BY ID — repeatable (``?ids=<id>&ids=<id>``), returning those messages IN FULL (whole body, attachment refs and all), oldest→newest.
	//
	// This is what makes the wake snapshot's fold marker honest (T-a828). ``ChatMessageDTO.body_omitted_chars`` > 0 says THIS message is here with part of its text folded away and tells the reader to re-read it with get_chat — but until this parameter existed get_chat took only a peer plus a paging cursor, so there was NO WAY TO NAME THE FOLDED MESSAGE. The promise beside the fold was not keepable, which made folding a silent drop.
	//
	// ANSWERED ON ITS OWN: when ``ids`` is present, ``with``, ``limit``, ``before_ts``/``before_id`` and ``peek`` are NOT consulted, and a by-ids read NEVER advances a read watermark — re-reading a message you were already shown is not reading the conversation. Blank entries are dropped and duplicates collapse; an all-blank or empty set behaves exactly as if the parameter had not been sent.
	//
	// SAME REACH AS THE ORDINARY LISTING (T-4e95, owner ruling). A by-ids read is NOT narrowed to the caller's own conversations. It used to refuse with 403 any id whose ``sender`` and ``recipient`` were both someone else — and that bound guarded nothing, because the ordinary listing filters on ``with`` — a PARTICIPANT — not on the caller, so the very same message was already readable by asking for that peer's line (designed behaviour; ``caller_only`` is what narrows a listing to the caller). What the stricter rule actually produced was two doors onto the same rows disagreeing about who may open them, which cost an honest caller the ability to follow a ``reply_to`` while costing a dishonest one nothing. This door now states the listing's rule rather than a stricter one of its own; ``caller_only`` remains the way to narrow a read to yourself.
	//
	// ALL OR NOTHING ON AN UNKNOWN ID: an id no message carries refuses the WHOLE call with 404 and names it. Deliberately not 'skip it and return the rest': a short array is indistinguishable from the fold this parameter exists to undo, so a caller could not tell a deleted message from one it simply did not ask for.
	//
	// AT MOST 20 DISTINCT IDS per call (counted after blanks are dropped); more is a 400 that states the limit. The cap is the response bound: 20 × the 4,000-rune body cap is the worst case one call can emit. It is not 'unfold a whole snapshot in one call' — name the ones that matter and call again.
	Ids *[]string `form:"ids,omitempty" json:"ids,omitempty"`
}

